const updateOnboardingTask = `-- name: UpdateOnboardingTask :execrows
UPDATE hr.onboarding_tasks SET task_name = $2, due_date = $3, is_completed = $4,
    completed_at = CASE WHEN $4 AND NOT is_completed THEN now() WHEN NOT $4 THEN NULL ELSE completed_at END,
    completed_by = CASE WHEN $4 AND NOT is_completed THEN $6 WHEN NOT $4 THEN NULL ELSE completed_by END,
    notes = $5, updated_at = now()
WHERE id = $1
`

type UpdateOnboardingTaskParams struct {
	ID          string
	TaskName    string
	DueDate     *time.Time
	IsCompleted bool
	Notes       string
	CompletedBy *string
}

